        ['id' => 100101, 'event_id' => 1001, 'type' => 'text_overlay', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['text' => 'Crew quarters', 'alignment' => 'top center', 'text_font_size' => 30, 'duration' => 2500]],
        ['id' => 101001, 'event_id' => 1010, 'type' => 'jump', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['scene_id' => 9, 'spawn_point' => 'left-door']],
        ['id' => 102001, 'event_id' => 1020, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['content' => '<h3>Sleeping in space</h3><p>There is no "up" in orbit, so the crew sleep strapped into their bunks to stop themselves drifting off.</p><p>The ship circles the planet many times a day, so the lights are dimmed on a 24-hour timetable to keep everyone\'s body clock steady.</p>']],
        ['id' => 103001, 'event_id' => 1030, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['content' => '<h3>The view outside</h3><p>From up here you can see a planet\'s day side and its night side at once.</p><p><em>Think about it:</em> a planet turns, so which way does its sunrise line move?</p>']],
        ['id' => 104001, 'event_id' => 1040, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['name' => 'learned_dance', 'operator' => 'set', 'operand' => 1]],
        ['id' => 104002, 'event_id' => 1040, 'type' => 'animate', 'sequence' => 2, 'blocking' => false, 'media_id' => NULL, 'params' => ['target' => 'player', 'animation' => 'dance']],
        ['id' => 104003, 'event_id' => 1040, 'type' => 'text_overlay', 'sequence' => 3, 'blocking' => true, 'media_id' => NULL, 'params' => ['text' => 'The crew’s favourite song comes on, and you pick up the steps. You can dance whenever you like now: look for the Dance button.', 'alignment' => 'bottom center', 'text_font_size' => 26, 'duration' => 5000]],
        ['id' => 110101, 'event_id' => 1101, 'type' => 'text_overlay', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['text' => 'Hydroponics bay', 'alignment' => 'top center', 'text_font_size' => 30, 'duration' => 2500]],
        ['id' => 111001, 'event_id' => 1110, 'type' => 'jump', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['scene_id' => 9, 'spawn_point' => 'right-door']],
        ['id' => 112001, 'event_id' => 1120, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['content' => '<h3>Plants without soil</h3><p>These plants grow with their roots in water. Everything they would take from soil is dissolved in it.</p><p>The ship keeps this water close to neutral, at about <strong>pH 6</strong>, which is what most plants like.</p>']],
        ['id' => 113001, 'event_id' => 1130, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['content' => '<h3>Why the lights are purple</h3><p>Leaves use mostly red and blue light to make food from water and carbon dioxide. Mixing red and blue lamps looks purple to us.</p><p>The plants return the favour: they give off the oxygen the crew breathes.</p>']],
        ['id' => 114001, 'event_id' => 1140, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['content' => '<h3>Nothing is wasted</h3><p>Water the plants do not use drains back into this tank, is cleaned, and goes round again.</p>']],
        ['id' => 120101, 'event_id' => 1201, 'type' => 'text_overlay', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['text' => 'Engine room', 'alignment' => 'top center', 'text_font_size' => 30, 'duration' => 2500]],
        ['id' => 121001, 'event_id' => 1210, 'type' => 'jump', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['scene_id' => 9, 'spawn_point' => 'far']],
        ['id' => 122001, 'event_id' => 1220, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['content' => '<h3>The reactor</h3><p>The glow is hot gas held in place by magnets, so it never touches the walls. It turns a tiny amount of fuel into a great deal of energy.</p><p>Energy is never made from nothing. Here it changes form: from fuel, to heat, to electricity for the whole ship.</p>']],
        ['id' => 123001, 'event_id' => 1230, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['content' => '<h3>Keeping it steady</h3><p>The green line shows the reactor\'s output over the last hour. The engineers want it flat: steady power, no surprises.</p>']],
        ['id' => 124001, 'event_id' => 1240, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['content' => '<h3>Three pipes, three jobs</h3><p>Orange carries heat away from the reactor, blue brings cooled liquid back, and grey is the spare.</p><p>If the heat had nowhere to go, the reactor would have to shut down.</p>']],
        ['id' => 130101, 'event_id' => 1301, 'type' => 'text_overlay', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['text' => 'Marketplace', 'alignment' => 'top center', 'text_font_size' => 30, 'duration' => 2500]],
        ['id' => 131001, 'event_id' => 1310, 'type' => 'jump', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['scene_id' => 9, 'spawn_point' => 'market-door']],
        ['id' => 132001, 'event_id' => 1320, 'type' => 'shop', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => []],
        ['id' => 133001, 'event_id' => 1330, 'type' => 'shop', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => []],
        ['id' => 134001, 'event_id' => 1340, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => NULL, 'params' => ['content' => '<h3>Stars and ranks</h3><p><b>Stars</b> are earned on missions and spent here, on things to wear, pets, new ways to move and abilities. You have <b>{{QL_PlayerStars}}</b>.</p><p><b>XP</b> is experience. It is never spent: it adds up, and as it grows you rise through the ranks. You have <b>{{QL_PlayerXP}}</b> XP.</p><p>Your rank: <b>{{QL_PlayerRank}}</b>. Both stars and XP stay with your account from mission to mission, so you need to be signed in to earn them.</p>']],
        ['id' => 90021, 'event_id' => 9002, 'type' => 'dialogue', 'sequence' => 1, 'blocking' => true, 'params' => ['style' => 'portrait', 'speaker' => 'character', 'character_id' => 2, 'text' => 'Mind the coolant pipes, {{QL_PlayerName}}. Orange is hot.']],
        ['id' => 90022, 'event_id' => 9002, 'type' => 'dialogue', 'sequence' => 2, 'blocking' => true, 'params' => ['style' => 'portrait', 'speaker' => 'character', 'character_id' => 2, 'text' => 'If a light on that wall starts blinking, it only means the reactor is thinking. Probably.']],
        ['id' => 90031, 'event_id' => 9003, 'type' => 'dialogue', 'sequence' => 1, 'blocking' => true, 'params' => ['style' => 'portrait', 'speaker' => 'character', 'character_id' => 3, 'text' => 'Everything green in here ends up on someone\'s plate, or in their lungs as fresh air.']],
        ['id' => 90032, 'event_id' => 9003, 'type' => 'dialogue', 'sequence' => 2, 'blocking' => true, 'params' => ['style' => 'portrait', 'speaker' => 'character', 'character_id' => 3, 'text' => 'Have a look at the racks. The plants will not mind.']],
        ['id' => 90041, 'event_id' => 9004, 'type' => 'dialogue', 'sequence' => 1, 'blocking' => true, 'params' => ['style' => 'portrait', 'speaker' => 'character', 'character_id' => 4, 'text' => 'Welcome to the marketplace. Stars you earn on missions are spent here.']],
        ['id' => 90042, 'event_id' => 9004, 'type' => 'dialogue', 'sequence' => 2, 'blocking' => true, 'params' => ['style' => 'portrait', 'speaker' => 'character', 'character_id' => 4, 'text' => 'The stalls are for new things; the wardrobe is for changing what you already own.']],
